	// Errors:
	//   - `not_found`: the combat is not this campaign's.
	//   - `permission_denied`: the caller is a player.
	EndEncounter(context.Context, *connect.Request[v1.EndEncounterRequest]) (*connect.Response[v1.EndEncounterResponse], error)
